/* Placeholder bootstrap.bundle.min.js
   This file intentionally includes only small helpers and no full Bootstrap implementation.
   It allows the page not to fail when the CDN is blocked. To get full Bootstrap behaviour,
   replace this file with the official bootstrap.bundle.min.js (v5.3.0).

   See ASSETS_README.md for commands to download the real files. */

// Minimal helper: provide a simple Modal API shim so calls like new bootstrap.Modal(...) don't throw.
window.bootstrap = window.bootstrap || {};
(function(ns){
  function Modal(element){
    this._el = element instanceof HTMLElement ? element : document.querySelector(element);
  }
  Modal.prototype.show = function(){
    if(!this._el) return; this._el.classList.add('show'); this._el.style.display = 'block';
  };
  Modal.prototype.hide = function(){
    if(!this._el) return; this._el.classList.remove('show'); this._el.style.display = 'none';
  };

  ns.Modal = Modal;

  // Collapse: data-bs-toggle="collapse" simple toggler
  function initCollapses(){
    document.addEventListener('click', function(e){
      const t = e.target.closest('[data-bs-toggle="collapse"]');
      if(!t) return;
      const sel = t.getAttribute('data-bs-target') || t.getAttribute('href');
      if(!sel) return;
      const target = document.querySelector(sel);
      if(!target) return;
      target.classList.toggle('show');
      target.style.display = target.classList.contains('show') ? 'block' : 'none';
    });
  }

  // init on DOM ready
  if(document.readyState === 'loading') document.addEventListener('DOMContentLoaded', initCollapses);
  else initCollapses();

})(window.bootstrap);

// End of placeholder bootstrap.bundle.min.js